<style>
.pp-page{padding:22px}.pp-summary{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:11px;margin-bottom:18px}.pp-stat{padding:15px 17px;border:1px solid #d5e5ec;border-radius:13px;background:#fff;box-shadow:0 5px 14px rgba(20,73,97,.04)}.pp-stat i{float:right;color:#7db8c7;font-size:18px}.pp-stat strong{display:block;color:#0b4668;font-size:21px;font-weight:800}.pp-stat span{color:#708c9f;font-size:11px}.pp-toolbar{display:flex;align-items:flex-end;justify-content:space-between;gap:14px;padding:16px 20px;border-bottom:1px solid #dce8ed}.pp-toolbar form{display:flex;align-items:flex-end;gap:9px}.pp-toolbar label{display:block;margin-bottom:5px;color:#244a63;font-size:11px;font-weight:800;text-transform:uppercase}.pp-toolbar .form-control{min-width:125px;height:40px;border-color:#c8dce5;border-radius:8px}.pp-toolbar .btn{height:40px;border-radius:8px;font-weight:700}.pp-note{max-width:520px;margin:0;color:#6c8799;font-size:12px}.pp-table-wrap{padding:8px 18px 15px;overflow-x:auto}.pp-table{min-width:1080px;margin:0}.pp-table thead th{padding:12px 10px;background:#f1f6f8;color:#173f5c;border-bottom:1px solid #d6e3e9;font-size:10px;text-transform:uppercase}.pp-table td{padding:12px 10px;vertical-align:middle;border-bottom:1px solid #e2ebef;color:#294a61}.pp-month{display:flex;align-items:center;gap:9px;color:#083f62;font-weight:800}.pp-month b{display:grid;place-items:center;width:27px;height:27px;border-radius:8px;color:#087ba0;background:#e1f5f8;font-size:11px}.pp-money{color:#087b69;font-weight:800;white-space:nowrap}.pp-total{color:#07547e;font-weight:900;white-space:nowrap}.pp-detail-btn{border-radius:8px;font-size:11px;font-weight:800;white-space:nowrap}.pp-chart{padding:10px 22px 22px}.pp-chart-inner{position:relative;height:250px;padding:15px;border:1px solid #deeaee;border-radius:12px;background:#fbfdfe}.pp-detail{display:none}.pp-detail.is-visible{display:block}.pp-detail-loading{padding:40px;text-align:center;color:#718c9e}.pp-doctor{display:flex;